mkitem!{declare_lint ! { # [doc = " The `noop_method_call` lint detects specific calls to noop methods"] # [doc = " such as a calling `<&T as Clone>::clone` where `T: !Clone`."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # #![allow(unused)]"] # [doc = " struct Foo;"] # [doc = " let foo = &Foo;"] # [doc = " let clone: &Foo = foo.clone();"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Some method calls are noops meaning that they do nothing. Usually such methods"] # [doc = " are the result of blanket implementations that happen to create some method invocations"] # [doc = " that end up not doing anything. For instance, `Clone` is implemented on all `&T`, but"] # [doc = " calling `clone` on a `&T` where `T` does not implement clone, actually doesn't do anything"] # [doc = " as references are copy. This lint detects these calls and warns the user about them."] pub NOOP_METHOD_CALL , Warn , "detects the use of well-known noop methods" }}
mkitem!{declare_lint ! { # [doc = " The `suspicious_double_ref_op` lint checks for usage of `.clone()`/`.borrow()`/`.deref()`"] # [doc = " on an `&&T` when `T: !Deref/Borrow/Clone`, which means the call will return the inner `&T`,"] # [doc = " instead of performing the operation on the underlying `T` and can be confusing."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # #![allow(unused)]"] # [doc = " struct Foo;"] # [doc = " let foo = &&Foo;"] # [doc = " let clone: &Foo = foo.clone();"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Since `Foo` doesn't implement `Clone`, running `.clone()` only dereferences the double"] # [doc = " reference, instead of cloning the inner type which should be what was intended."] pub SUSPICIOUS_DOUBLE_REF_OP , Warn , "suspicious call of trait method on `&&T`" }}
mkitem!{declare_lint_pass ! (NoopMethodCall => [NOOP_METHOD_CALL , SUSPICIOUS_DOUBLE_REF_OP]) ;}
mkitem!{mkimpl!{impl < 'tcx > LateLintPass < 'tcx > for NoopMethodCall { fn check_expr (& mut self , cx : & LateContext < 'tcx > , expr : & 'tcx Expr < '_ >) { let ExprKind :: MethodCall (call , receiver , _ , call_span) = & expr . kind else { return ; } ; if call_span . from_expansion () { return ; } let Some ((DefKind :: AssocFn , did)) = cx . typeck_results () . type_dependent_def (expr . hir_id) else { return ; } ; let Some (trait_id) = cx . tcx . trait_of_assoc (did) else { return } ; let Some (trait_) = cx . tcx . get_diagnostic_name (trait_id) else { return } ; if ! matches ! (trait_ , sym :: Borrow | sym :: Clone | sym :: Deref) { return ; } ; let args = cx . tcx . normalize_erasing_regions (cx . typing_env () , cx . typeck_results () . node_args (expr . hir_id)) ; let Ok (Some (i)) = ty :: Instance :: try_resolve (cx . tcx , cx . typing_env () , did , args) else { return ; } ; let Some (name) = cx . tcx . get_diagnostic_name (i . def_id ()) else { return } ; if ! matches ! (name , sym :: noop_method_borrow | sym :: noop_method_clone | sym :: noop_method_deref) { return ; } let receiver_ty = cx . typeck_results () . expr_ty (receiver) ; let expr_ty = cx . typeck_results () . expr_ty_adjusted (expr) ; let arg_adjustments = cx . typeck_results () . expr_adjustments (receiver) ; if arg_adjustments . iter () . any (| adj | matches ! (adj . kind , Adjust :: Deref (Some (_)))) { return ; } let expr_span = expr . span ; let span = expr_span . with_lo (receiver . span . hi ()) ; let orig_ty = expr_ty . peel_refs () ; if receiver_ty == expr_ty { let suggest_derive = match orig_ty . kind () { ty :: Adt (def , _) => Some (cx . tcx . def_span (def . did ()) . shrink_to_lo ()) , _ => None , } ; cx . emit_span_lint (NOOP_METHOD_CALL , span , NoopMethodCallDiag { method : call . ident , orig_ty , trait_ , label : span , suggest_derive , } ,) ; } else { match name { sym :: noop_method_borrow => return , sym :: noop_method_clone => cx . emit_span_lint (SUSPICIOUS_DOUBLE_REF_OP , span , SuspiciousDoubleRefCloneDiag { ty : expr_ty } ,) , sym :: noop_method_deref => cx . emit_span_lint (SUSPICIOUS_DOUBLE_REF_OP , span , SuspiciousDoubleRefDerefDiag { ty : expr_ty } ,) , _ => return , } } } }}}